CREATE TABLE tenants(id BINARY(16) PRIMARY KEY,slug VARCHAR(120) NOT NULL UNIQUE,name VARCHAR(200) NOT NULL,status VARCHAR(30) NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL);
CREATE TABLE organizations(id BINARY(16) PRIMARY KEY,tenant_id BINARY(16) NOT NULL,slug VARCHAR(120) NOT NULL,name VARCHAR(200) NOT NULL,type VARCHAR(30) NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,UNIQUE(tenant_id,slug),FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE tenant_members(id BINARY(16) PRIMARY KEY,tenant_id BINARY(16) NOT NULL,user_id BINARY(16) NOT NULL,status VARCHAR(30) NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,UNIQUE(tenant_id,user_id),FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE permissions(id BINARY(16) PRIMARY KEY,code VARCHAR(150) NOT NULL UNIQUE,description VARCHAR(500),created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL);
CREATE TABLE roles(id BINARY(16) PRIMARY KEY,tenant_id BINARY(16) NOT NULL,code VARCHAR(100) NOT NULL,name VARCHAR(150) NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,UNIQUE(tenant_id,code),FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE role_permissions(role_id BINARY(16) NOT NULL,permission_id BINARY(16) NOT NULL,PRIMARY KEY(role_id,permission_id),FOREIGN KEY(role_id) REFERENCES roles(id),FOREIGN KEY(permission_id) REFERENCES permissions(id));
CREATE TABLE member_roles(id BINARY(16) PRIMARY KEY,member_id BINARY(16) NOT NULL,role_id BINARY(16) NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,UNIQUE(member_id,role_id),FOREIGN KEY(member_id) REFERENCES tenant_members(id),FOREIGN KEY(role_id) REFERENCES roles(id));
